from pathlib import Path
p=Path('src/main.jsx')
s=p.read_text()
start=s.find('function AdminTasks(')
end=s.find('function AdminFinance(', start)
if start<0 or end<0: raise SystemExit('AdminTasks/AdminFinance boundary not found')
fn=r'''function AdminTasks({p}){
 const [giras,setGiras]=useState([]),[cats,setCats]=useState([]),[tasks,setTasks]=useState([]),[people,setPeople]=useState([]),[responses,setResponses]=useState([]),[editing,setEditing]=useState(null),[newTask,setNewTask]=useState(null),[selected,setSelected]=useState(''),[msg,setMsg]=useState(''),[busy,setBusy]=useState(false)
 const load=async()=>{const[{data:gs,error:e1},{data:cs,error:e2}]=await Promise.all([supabase.from('giras').select('*').order('starts_at',{ascending:false}),supabase.from('task_categories').select('id,name,is_operational_default').order('name')]);if(e1||e2){setMsg((e1||e2).message);return}setGiras(gs||[]);setCats(cs||[]);if(!selected&&gs?.[0])setSelected(gs[0].id)}
 const loadGira=async id=>{if(!id)return;const[{data:ts,error:e1},{data:ps,error:e2},{data:rs,error:e3}]=await Promise.all([supabase.from('tasks').select('*,task_categories(id,name),task_assignments(id,profile_id,assignment_mode,profiles(id,name,orixa_symbol))').eq('gira_id',id).order('period_key').order('sort_order'),supabase.from('profiles').select('id,name,orixa_symbol,group_id,is_iniciado,is_active,leadership_seal,groups(name)').eq('is_active',true).order('name'),supabase.from('gira_responses').select('id,profile_id,status,gira_availability(period_key)').eq('gira_id',id)]);if(e1||e2||e3){setMsg((e1||e2||e3).message);return}setTasks(ts||[]);setPeople(ps||[]);setResponses(rs||[])}
 useEffect(()=>{load()},[]);useEffect(()=>{loadGira(selected)},[selected])
 const create=async()=>{if(!newTask?.name||!newTask.period_key||!newTask.category_id)return;setBusy(true);const{error}=await supabase.rpc('create_task',{p_gira_id:selected,p_name:newTask.name,p_period_key:newTask.period_key,p_slots:Number(newTask.slots||1),p_category_id:newTask.category_id});if(error)setMsg(error.message);else{setNewTask(null);await loadGira(selected)}setBusy(false)}
 const update=async()=>{if(!editing)return;setBusy(true);const{error}=await supabase.rpc('update_task',{p_task_id:editing.id,p_name:editing.name,p_period_key:editing.period_key,p_slots:Number(editing.slots),p_category_id:editing.category_id});if(error)setMsg(error.message);else{setEditing(null);await loadGira(selected)}setBusy(false)}
 const remove=async id=>{if(!window.confirm('Excluir esta tarefa?'))return;const{error}=await supabase.rpc('delete_task',{p_task_id:id});if(error)setMsg(error.message);else await loadGira(selected)}
 const draw=async()=>{setBusy(true);const{error}=await supabase.rpc('draw_gira_tasks',{p_gira_id:selected});if(error)setMsg(error.message);else{setMsg('Sorteio concluído.');await loadGira(selected)}setBusy(false)}
 const assign=async(taskId,profileId)=>{if(!profileId)return;setBusy(true);const{error}=await supabase.rpc('editor_assign_task',{p_task_id:taskId,p_profile_id:profileId,p_mode:'manual'});if(error)setMsg(error.message);else await loadGira(selected);setBusy(false)}
 const removeAssignment=async id=>{const{error}=await supabase.rpc('admin_remove_task_assignment',{p_assignment_id:id});if(error)setMsg(error.message);else await loadGira(selected)}
 const selectedGira=giras.find(g=>g.id===selected);const eligible=people
 return <div className="card"><div className="row between"><div><span className="eyebrow">TAREFAS</span><h2 style={{margin:'6px 0'}}>Organização da gira</h2><p className="muted small">Sorteio, liderança e ajustes manuais.</p></div><button className="btn" onClick={load}><RefreshCw size={15}/> Atualizar</button></div>{msg&&<div className="toast">{msg}</div>}<div className="field"><label>Gira</label><select className="select" value={selected} onChange={e=>setSelected(e.target.value)}><option value="">Escolha uma gira</option>{giras.map(g=><option key={g.id} value={g.id}>{g.name} · {dateOnly(g.starts_at)}</option>)}</select></div>{selectedGira&&<><div className="row"><button className="btn primary" disabled={busy} onClick={draw}>Sortear tarefas</button><button className="btn" onClick={()=>setNewTask({name:'',period_key:'friday',slots:1,category_id:cats[0]?.id||''})}><Plus size={15}/> Nova tarefa</button></div><div className="list">{tasks.map(t=><div className="list-item" key={t.id}><div className="row between"><div><b>{t.name}</b><div className="muted small">{t.period_key} · {t.task_categories?.name} · {t.slots} vaga(s)</div></div><div className="row"><button className="btn" onClick={()=>setEditing({...t,category_id:t.category_id})}>Editar</button><button className="btn danger" onClick={()=>remove(t.id)}><Trash2 size={14}/></button></div></div>{(t.task_assignments||[]).map(a=><div className="row between" key={a.id} style={{marginTop:7}}><span className="small">{a.profiles?.name||'Pessoa'} · {a.assignment_mode==='leader_choice'?'Liderança':'Atribuída'}</span><button className="btn danger" onClick={()=>removeAssignment(a.id)}><X size={13}/></button></div>)}<div className="field"><label>Atribuir manualmente</label><select className="select" defaultValue="" onChange={e=>{assign(t.id,e.target.value);e.target.value=''}}><option value="">Escolha uma pessoa</option>{eligible.filter(x=>!(t.task_assignments||[]).some(a=>a.profile_id===x.id)).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></div></div>)}{tasks.length===0&&<div className="empty">Nenhuma tarefa cadastrada nesta gira.</div>}</div></>}{newTask&&<div className="modal-back"><div className="modal"><h3>Nova tarefa</h3><div className="field"><label>Nome</label><input className="input" value={newTask.name} onChange={e=>setNewTask({...newTask,name:e.target.value})}/></div><div className="field"><label>Período</label><select className="select" value={newTask.period_key} onChange={e=>setNewTask({...newTask,period_key:e.target.value})}>{periods.map(x=><option key={x[0]} value={x[0]}>{x[1]}</option>)}</select></div><div className="field"><label>Vagas</label><input className="input" type="number" min="1" value={newTask.slots} onChange={e=>setNewTask({...newTask,slots:e.target.value})}/></div><div className="field"><label>Categoria</label><select className="select" value={newTask.category_id} onChange={e=>setNewTask({...newTask,category_id:e.target.value})}>{cats.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></div><div className="row"><button className="btn" onClick={()=>setNewTask(null)}>Cancelar</button><button className="btn primary" disabled={busy} onClick={create}>Criar</button></div></div></div>}{editing&&<div className="modal-back"><div className="modal"><h3>Editar tarefa</h3><div className="field"><label>Nome</label><input className="input" value={editing.name} onChange={e=>setEditing({...editing,name:e.target.value})}/></div><div className="field"><label>Período</label><select className="select" value={editing.period_key} onChange={e=>setEditing({...editing,period_key:e.target.value})}>{periods.map(x=><option key={x[0]} value={x[0]}>{x[1]}</option>)}</select></div><div className="field"><label>Vagas</label><input className="input" type="number" min="1" value={editing.slots} onChange={e=>setEditing({...editing,slots:e.target.value})}/></div><div className="field"><label>Categoria</label><select className="select" value={editing.category_id} onChange={e=>setEditing({...editing,category_id:e.target.value})}>{cats.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></div><div className="row"><button className="btn" onClick={()=>setEditing(null)}>Cancelar</button><button className="btn primary" disabled={busy} onClick={update}>Salvar</button></div></div></div>}</div>}
'''
p.write_text(s[:start]+fn+'\n'+s[end:])
